import{_ as o}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as e,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const C=JSON.parse('{"title":"GitHub Copilot 学习导航","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/copilot/index.md","filePath":"zh/products/ai-coding/copilot/index.md","lastUpdated":1787046041000}'),r={name:"zh/products/ai-coding/copilot/index.md"};function d(n,t,l,i,p,h){return e(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="github-copilot-学习导航" tabindex="-1">GitHub Copilot 学习导航 <a class="header-anchor" href="#github-copilot-学习导航" aria-label="Permalink to &quot;GitHub Copilot 学习导航&quot;">​</a></h1><blockquote><p>GitHub Copilot 是一套共享订阅、但入口 / 自主程度 / 副作用范围完全不同的 AI 编程产品族。本页是全景图和决策树——<strong>先分清形态，再决定学什么</strong>。</p></blockquote><h2 id="产品全景图" tabindex="-1">产品全景图 <a class="header-anchor" href="#产品全景图" aria-label="Permalink to &quot;产品全景图&quot;">​</a></h2><p>官方功能清单见 <a href="https://docs.github.com/en/copilot/get-started/features" target="_blank" rel="noreferrer">GitHub Copilot features</a>。同步辅助类工具<strong>和你一起工作</strong>；agent 类工具<strong>可以在你不盯着的时候跑</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GitHub Copilot</span></span>
<span class="line"><span>├── IDE — VS Code / Visual Studio / JetBrains / Xcode / Eclipse</span></span>
<span class="line"><span>│   ├── 行内补全（灰字；VS Code / Xcode / Eclipse 还有 next-edit suggestions）</span></span>
<span class="line"><span>│   └── Chat：Ask / Edit / Agent 模式（Agent 模式跑在本地）</span></span>
<span class="line"><span>├── github.com — Web（对位 Claude 的 Web）</span></span>
<span class="line"><span>│   ├── Copilot Chat（https://github.com/copilot，或任意仓库 / Issue / PR）</span></span>
<span class="line"><span>│   ├── Cloud agent — 调研 / 计划 / 改分支 / 可选开 PR（付费计划）</span></span>
<span class="line"><span>│   ├── 代码审查</span></span>
<span class="line"><span>│   └── PR 摘要</span></span>
<span class="line"><span>├── Copilot CLI — 终端（对位 Claude 的 CLI）</span></span>
<span class="line"><span>│   ├── 交互式会话（\`copilot\`）</span></span>
<span class="line"><span>│   └── 编程式调用（\`copilot -p &quot;...&quot;\`）</span></span>
<span class="line"><span>├── Copilot app — 桌面（对位 Claude 的 Desktop）</span></span>
<span class="line"><span>│   └── 并行 agent 会话、Issues / PR、定时自动化</span></span>
<span class="line"><span>├── GitHub Mobile</span></span>
<span class="line"><span>└── GitHub Desktop — 只生成 commit message</span></span></code></pre></div><p><strong>不要再新开这些。</strong> 它们已日落或正在关闭：</p><table tabindex="0"><thead><tr><th>产品</th><th>现状</th><th>替代</th></tr></thead><tbody><tr><td><strong>Copilot Workspace</strong></td><td><strong>2025-05-30</strong> 日落</td><td>Cloud agent</td></tr><tr><td><strong>GitHub App Copilot Extensions</strong></td><td><strong>2025-11-10</strong> 日落</td><td>MCP</td></tr><tr><td><strong><code>gh copilot</code></strong></td><td>官方已标 <strong>retired</strong></td><td>独立 <code>copilot</code> CLI</td></tr><tr><td><strong>GitHub Spark</strong></td><td><strong>2026-08-04</strong> 起不再接受新用户、不能新建应用；已有应用须在 <strong>2026-08-31</strong> 前导出</td><td>在 IDE、CLI 或 Copilot app 里做</td></tr></tbody></table><p>Spark 是用自然语言搭微应用的产品。对前端读者相关度中等，密度不够单独成页——而且已经在关停。如果你已经有 Spark，在 workbench 里点 <code>…</code> → <strong>Create repository</strong>，在 2026-08-31 前导出。官方公告：<a href="https://github.blog/changelog/2026-08-04-upcoming-deprecation-of-github-spark-on-github-com/" target="_blank" rel="noreferrer">Spark deprecation</a>。</p><h3 id="快速决策-我该用哪个" tabindex="-1">快速决策：我该用哪个？ <a class="header-anchor" href="#快速决策-我该用哪个" aria-label="Permalink to &quot;快速决策：我该用哪个？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我现在要干什么？</span></span>
<span class="line"><span>├── 在编辑器里写 / 补全 / 重构</span></span>
<span class="line"><span>│   └── → IDE</span></span>
<span class="line"><span>│       ├── 补下一行 / 补样板          → 代码补全（Tab）</span></span>
<span class="line"><span>│       ├── 只想搞懂，别动我代码        → Chat Ask</span></span>
<span class="line"><span>│       ├── 我知道改哪几个文件          → Chat Edit</span></span>
<span class="line"><span>│       └── 我只给目标，过程你定        → Chat Agent（本地执行，有副作用）</span></span>
<span class="line"><span>├── 任务在命令行（脚本、git、构建排错，不在 IDE）</span></span>
<span class="line"><span>│   └── → Copilot CLI</span></span>
<span class="line"><span>│       ├── 多轮                           → \`copilot\`</span></span>
<span class="line"><span>│       └── 脚本里一次性调用               → \`copilot -p &quot;...&quot;\`</span></span>
<span class="line"><span>├── 人已经在 github.com 上（这个仓库 / 这个 Issue / 这个 PR）</span></span>
<span class="line"><span>│   └── → github.com</span></span>
<span class="line"><span>│       ├── 问这个仓库的事                 → Copilot Chat</span></span>
<span class="line"><span>│       ├── 边界清楚、耗时、不想守着       → Cloud agent</span></span>
<span class="line"><span>│       └── 审这个 PR                      → 代码审查</span></span>
<span class="line"><span>└── 要并行指挥多个 agent，不想待在 IDE 里</span></span>
<span class="line"><span>    └── → Copilot app（桌面）</span></span></code></pre></div><p>三个最常见的混淆，先记住：</p><table tabindex="0"><thead><tr><th>容易混的</th><th>区别</th></tr></thead><tbody><tr><td>Chat 的 <strong>Agent 模式</strong> vs <strong>Cloud agent</strong></td><td>前者跑在你本地机器上；后者跑在 GitHub 云端（Actions 临时环境），产出是分支 / PR。<a href="https://docs.github.com/en/copilot/concepts/agents/cloud-agent/about-cloud-agent" target="_blank" rel="noreferrer">官方对照</a></td></tr><tr><td>独立 <strong><code>copilot</code> CLI</strong> vs <strong><code>gh copilot</code></strong></td><td>前者是完整 agent，且已 <strong>GA</strong>；后者官方已 <strong>retired</strong>，只剩 explain / suggest</td></tr><tr><td><strong>Copilot app</strong> vs <strong>IDE Chat</strong></td><td>app 是架在 Copilot CLI 上的桌面壳：并行会话、Issues / PR、自动化。IDE Chat 待在编辑器里</td></tr></tbody></table><p>更多同类辨析见 <a href="./copilot-glossary.html">术语表</a>。</p><p>关键机制（决定了后面所有优化动作）：Copilot 不是「把你的仓库喂给模型训练」，而是<strong>每次请求时检索并注入上下文</strong>。所以「仓库大 = Copilot 懂得多」是错的；「打开相关文件再提问」才有效。</p><h2 id="核心概念速览" tabindex="-1">核心概念速览 <a class="header-anchor" href="#核心概念速览" aria-label="Permalink to &quot;核心概念速览&quot;">​</a></h2><p>详见 <a href="./copilot-glossary.html">术语表</a>。</p><table tabindex="0"><thead><tr><th>概念</th><th>一句话解释</th><th>出现位置</th></tr></thead><tbody><tr><td><strong>四个日常入口</strong></td><td>补全、IDE Chat、CLI、Cloud agent</td><td>全局</td></tr><tr><td><strong>Ask / Edit / Agent</strong></td><td><strong>IDE Chat 内部</strong>的三档自主程度</td><td>IDE</td></tr><tr><td><strong>Cloud agent</strong></td><td>GitHub 上的后台 agent；付费计划；Business / Enterprise 需管理员开启</td><td>github.com / Issue / VS Code</td></tr><tr><td><strong>Copilot CLI</strong></td><td>终端 agent（<code>copilot</code>）。不是 <code>gh copilot</code></td><td>终端</td></tr><tr><td><strong>Copilot app</strong></td><td>并行 agent 会话的桌面应用</td><td>桌面</td></tr><tr><td><strong>自定义指令</strong></td><td>自动附着的项目级约束</td><td>所有界面</td></tr><tr><td><strong>提示文件</strong></td><td><code>/name</code> 可复用任务</td><td>IDE Chat</td></tr><tr><td><strong>MCP</strong></td><td>连接外部工具的开放协议。取代了 GitHub App Extensions</td><td>所有 agent 界面</td></tr><tr><td><strong>Plugins / Skills</strong></td><td>可安装的 agent / skill / hook 包</td><td>CLI / Chat / app</td></tr><tr><td><strong>Spaces</strong></td><td>命名的上下文包（仓库 + 文件 + 说明）</td><td>github.com / Chat</td></tr><tr><td><strong>AI credits</strong></td><td>Chat、CLI、agent、审查的用量单位</td><td>计费</td></tr></tbody></table><h2 id="该读哪一篇" tabindex="-1">该读哪一篇 <a class="header-anchor" href="#该读哪一篇" aria-label="Permalink to &quot;该读哪一篇&quot;">​</a></h2><p>本组文档按 <a href="https://diataxis.fr/" target="_blank" rel="noreferrer">Diataxis</a> 四象限拆分，各有明确分工——<strong>别拿速查表当教程读</strong>：</p><table tabindex="0"><thead><tr><th>文档</th><th>类型</th><th>什么时候看</th></tr></thead><tbody><tr><td><a href="./copilot.html">上手教程</a></td><td>Tutorial</td><td>第一次用，想按顺序走一遍：装 → 登录 → 认识四个日常入口 → 沉淀项目规范</td></tr><tr><td><a href="./copilot-cookbook.html">实战 Cookbook</a></td><td>How-to</td><td>已经会基本操作，想照抄某个场景的现成做法</td></tr><tr><td><a href="./copilot-cheatsheet.html">Cheatsheet</a></td><td>Reference</td><td>查快捷键、斜杠命令、配置键名、CLI 参数、计划配额</td></tr><tr><td><a href="./copilot-glossary.html">术语表</a></td><td>Explanation</td><td>看到不认识的名词，或怀疑某个说法已经过时</td></tr></tbody></table><h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><h3 id="第一阶段-能用起来" tabindex="-1">第一阶段：能用起来 <a class="header-anchor" href="#第一阶段-能用起来" aria-label="Permalink to &quot;第一阶段：能用起来&quot;">​</a></h3><p><strong>目标</strong>：装好、登录，理解检索式上下文注入。</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>链接</th></tr></thead><tbody><tr><td>1</td><td>选订阅——有免费档</td><td><a href="./copilot.html">教程 · 第 0 步</a></td></tr><tr><td>2</td><td>装 IDE 扩展并登录；需要终端能力再另装 CLI</td><td><a href="./copilot.html">教程 · 第 1 步</a></td></tr><tr><td>3</td><td>理解上下文注入机制，这是后面一切优化的前提</td><td><a href="./copilot.html">教程 · 第 2 步</a></td></tr></tbody></table><h3 id="第二阶段-选对入口" tabindex="-1">第二阶段：选对入口 <a class="header-anchor" href="#第二阶段-选对入口" aria-label="Permalink to &quot;第二阶段：选对入口&quot;">​</a></h3><p><strong>目标</strong>：别再付「选错形态」的税。</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>链接</th></tr></thead><tbody><tr><td>4</td><td>IDE vs github.com vs CLI vs 云端 vs 桌面</td><td>上面的决策树；<a href="./copilot.html">教程 · 第 3 步</a></td></tr><tr><td>5</td><td>Ask / Edit / Agent 形成肌肉记忆</td><td><a href="./copilot-glossary.html">术语表 · 三种模式</a></td></tr><tr><td>6</td><td>用 <code>@</code> 和 <code>#</code> 显式喂上下文</td><td><a href="./copilot-cheatsheet.html">Cheatsheet · 聊天参与者</a></td></tr></tbody></table><h3 id="第三阶段-把重复的沉淀下来" tabindex="-1">第三阶段：把重复的沉淀下来 <a class="header-anchor" href="#第三阶段-把重复的沉淀下来" aria-label="Permalink to &quot;第三阶段：把重复的沉淀下来&quot;">​</a></h3><p><strong>目标</strong>：同一句话只写一次。</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>链接</th></tr></thead><tbody><tr><td>7</td><td>写 <code>.github/copilot-instructions.md</code></td><td><a href="./copilot-cookbook.html">Cookbook · 沉淀项目规范</a></td></tr><tr><td>8</td><td>用提示文件处理成型任务</td><td><a href="./copilot-cookbook.html">Cookbook · 复用提示文件</a></td></tr><tr><td>9</td><td>接 MCP 访问数据库、内部 API</td><td><a href="./copilot-glossary.html">术语表 · MCP</a></td></tr></tbody></table><h3 id="第四阶段-规模化与安全" tabindex="-1">第四阶段：规模化与安全 <a class="header-anchor" href="#第四阶段-规模化与安全" aria-label="Permalink to &quot;第四阶段：规模化与安全&quot;">​</a></h3><p><strong>目标</strong>：会派活，会审查。</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>链接</th></tr></thead><tbody><tr><td>10</td><td>派活给 Cloud agent，任务描述写清硬边界</td><td><a href="./copilot-cookbook.html">Cookbook · 把任务扔到云端</a></td></tr><tr><td>11</td><td>权限判断、SQL 拼接、加密、支付相关代码永远人工过一遍</td><td><a href="./copilot.html">教程 · 第 6 步</a></td></tr></tbody></table><h2 id="功能速查表" tabindex="-1">功能速查表 <a class="header-anchor" href="#功能速查表" aria-label="Permalink to &quot;功能速查表&quot;">​</a></h2><h3 id="同步辅助-你一直在环里" tabindex="-1">同步辅助（你一直在环里） <a class="header-anchor" href="#同步辅助-你一直在环里" aria-label="Permalink to &quot;同步辅助（你一直在环里）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>用途</th><th>文档</th></tr></thead><tbody><tr><td>行内补全</td><td>下一行 / 样板代码，Tab 接受</td><td><a href="./copilot.html">教程</a></td></tr><tr><td>IDE Chat · Ask</td><td>解释、对比、计划——不改代码</td><td><a href="./copilot-glossary.html">术语表</a></td></tr><tr><td>IDE Chat · Edit</td><td>只改你点名的文件，给你看 diff</td><td><a href="./copilot-cookbook.html">Cookbook</a></td></tr><tr><td>github.com 上的 Copilot Chat</td><td>不问 IDE，直接问仓库 / Issue / PR</td><td><a href="https://docs.github.com/en/copilot/how-tos/copilot-on-github/chat-with-copilot/chat-in-github" target="_blank" rel="noreferrer">Ask questions in GitHub</a></td></tr><tr><td>PR 摘要</td><td>给 PR 生成 AI 摘要</td><td><a href="https://docs.github.com/en/copilot/how-tos/copilot-on-github/copilot-for-github-tasks/create-a-pr-summary" target="_blank" rel="noreferrer">Create a PR summary</a></td></tr><tr><td>GitHub Desktop</td><td>根据 diff 写 commit message</td><td><a href="https://docs.github.com/en/copilot/get-started/features" target="_blank" rel="noreferrer">Features</a></td></tr></tbody></table><h3 id="agent-能力-可以不盯着跑" tabindex="-1">Agent 能力（可以不盯着跑） <a class="header-anchor" href="#agent-能力-可以不盯着跑" aria-label="Permalink to &quot;Agent 能力（可以不盯着跑）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>用途</th><th>文档</th></tr></thead><tbody><tr><td>IDE Agent 模式</td><td>本地多步改动 + 命令（需你审批）</td><td><a href="./copilot-cookbook.html">Cookbook</a></td></tr><tr><td>Copilot CLI</td><td>终端 agent；交互式或 <code>copilot -p</code></td><td><a href="./copilot-cheatsheet.html">Cheatsheet · CLI</a> · <a href="https://docs.github.com/en/copilot/concepts/agents/copilot-cli/about-copilot-cli" target="_blank" rel="noreferrer">About CLI</a></td></tr><tr><td>Cloud agent</td><td>在 GitHub 上调研 / 计划 / 改分支 / 可选开 PR</td><td><a href="./copilot-cookbook.html">Cookbook</a> · <a href="https://docs.github.com/en/copilot/concepts/agents/cloud-agent/about-cloud-agent" target="_blank" rel="noreferrer">About cloud agent</a></td></tr><tr><td>Copilot app</td><td>桌面：并行会话、Issues / PR、自动化</td><td><a href="https://docs.github.com/en/copilot/concepts/agents/github-copilot-app" target="_blank" rel="noreferrer">About the Copilot app</a></td></tr><tr><td>代码审查</td><td>给 PR 写 AI 审查意见</td><td><a href="https://docs.github.com/en/copilot/how-tos/use-copilot-agents/request-a-code-review/use-code-review" target="_blank" rel="noreferrer">Code review</a></td></tr></tbody></table><h3 id="定制-横跨所有入口" tabindex="-1">定制（横跨所有入口） <a class="header-anchor" href="#定制-横跨所有入口" aria-label="Permalink to &quot;定制（横跨所有入口）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>用途</th><th>文档</th></tr></thead><tbody><tr><td>自定义指令</td><td>写一次，每次自动附着</td><td><a href="./copilot-cheatsheet.html">Cheatsheet</a></td></tr><tr><td>提示文件</td><td><code>/name</code> 可复用任务</td><td><a href="./copilot-cookbook.html">Cookbook</a></td></tr><tr><td>MCP</td><td>外部工具和数据</td><td><a href="./copilot-glossary.html">术语表</a></td></tr><tr><td>Skills / Plugins</td><td>专项知识包</td><td><a href="./copilot-glossary.html">术语表</a></td></tr><tr><td>Spaces</td><td>命名的上下文包</td><td><a href="./copilot-glossary.html">术语表</a></td></tr></tbody></table><h2 id="时效性提醒" tabindex="-1">时效性提醒 <a class="header-anchor" href="#时效性提醒" aria-label="Permalink to &quot;时效性提醒&quot;">​</a></h2><p>Copilot 迭代很快，旧教程里大量写法已经失效。下面几条是查资料时最容易踩的坑：</p><ul><li><strong>Copilot Workspace</strong>（GitHub Next 技术预览）<strong>已于 2025-05-30 日落</strong>。「Issue → 计划 → PR」现由 <strong>Cloud agent</strong> 承载。</li><li><strong>Copilot Extensions（GitHub App 形态）已于 2025-11-10 日落</strong>，官方替代方案是 MCP。VS Code 客户端侧的 Chat 扩展不受影响。</li><li><strong>GitHub Spark</strong> 自 <strong>2026-08-04</strong> 起不再接受新用户、不能新建应用；已有应用须在 <strong>2026-08-31</strong> 前导出。已部署的应用会继续跑。不要再写「从零做一个 Spark」的教程。</li><li><code>@workspace</code>、<code>#editor</code>、<code>#git</code>、<code>#vscodeAPI</code> 等旧引用<strong>已不在官方清单里</strong>——代码库检索下沉成了工具，Agent 模式自主调用。</li><li>曾叫 &quot;coding agent&quot; 的云端能力<strong>官方已改称 cloud agent</strong>。</li><li><strong><code>gh copilot</code>（GitHub CLI 扩展）官方已标 retired</strong>，由独立 <code>copilot</code> CLI 取代。</li><li>Copilot CLI 已 <strong>GA</strong>（自 <a href="https://github.blog/changelog/2026-02-25-github-copilot-cli-is-now-generally-available/" target="_blank" rel="noreferrer">2026-02-25</a>）。还写「public preview」的页面过时了。</li><li>Copilot <strong>在 GitHub Enterprise Server 上不可用</strong>。Enterprise 需要 GitHub Enterprise Cloud；Business / Enterprise 的额度差见 <a href="./copilot-cheatsheet.html">Cheatsheet · 计划对照</a>。</li></ul><p>完整的已退役/改名清单见 <a href="./copilot-glossary.html">术语表 · 已退役或已改名的概念</a>。</p><h2 id="资源链接" tabindex="-1">资源链接 <a class="header-anchor" href="#资源链接" aria-label="Permalink to &quot;资源链接&quot;">​</a></h2><ul><li><a href="https://docs.github.com/en/copilot" target="_blank" rel="noreferrer">GitHub Copilot 官方文档</a></li><li><a href="https://docs.github.com/en/copilot/get-started/features" target="_blank" rel="noreferrer">GitHub Copilot 功能清单</a></li><li><a href="https://code.visualstudio.com/docs/copilot/overview" target="_blank" rel="noreferrer">VS Code Copilot 文档</a></li><li><a href="./copilot-cheatsheet.html">Cheatsheet · 高质量信息源</a> — 按可信度排序的完整信息源清单，也是本组文档的核实依据</li></ul><blockquote><p><strong>取证注意</strong>：<code>docs.github.com</code> 中文版覆盖不全且滞后，<code>docs.github.com/zh/enterprise-cloud@latest/...</code> 这类路径大量已失效。核对事实统一用 <code>docs.github.com/en/copilot/...</code>。</p></blockquote>`,47)])])}const m=o(r,[["render",d]]);export{C as __pageData,m as default};
